<script setup lang="ts">
import { computed,ref,watch } from 'vue';
import { workspaceRequest,type FileReference,type SourceFile } from '../services/workspace';
import { downloadText } from '../utils/download';
const props=defineProps<{projectId:string;file:SourceFile|null;disabled?:boolean}>();
interface Report { checkedAt:string;status:string;selected:number;analyzed:number;imports:number;scope:string;files:FileReference[];findings:{path:string;line:number;rule:string;dependency:string;message:string}[];uncertainties:{path:string;line:number;reason:string}[] }
const selected=ref<FileReference[]>([]),prefix=ref('@/'),directory=ref('src'),report=ref<Report>(),busy=ref(false),error=ref('');let revision=0;
const canAdd=computed(()=>!!props.file&&!props.file.redacted&&(selected.value.length<50||selected.value.some(item=>item.path===props.file?.path)));
watch(()=>props.projectId,()=>{revision++;selected.value=[];report.value=undefined;error.value='';});
function add(){const file=props.file;if(!file||file.redacted)return;selected.value=[...selected.value.filter(item=>item.path!==file.path),{path:file.path,sha256:file.sha256}];report.value=undefined;}
async function check(){const token=++revision;busy.value=true;error.value='';report.value=undefined;try{const result=await workspaceRequest<Report>(props.projectId,'/architecture',{files:selected.value,aliases:prefix.value.trim()?[{prefix:prefix.value.trim(),directory:directory.value.trim()}]:[]});if(token===revision)report.value=result;}catch(cause){if(token===revision)error.value=(cause as Error).message;}finally{busy.value=false;}}
function download(){if(report.value)downloadText('ares-reglas-ddd.json',JSON.stringify(report.value,null,2),'application/json');}
</script>
<template><section class="architecture-check" aria-label="Reglas DDD"><h3>Reglas de dependencia DDD</h3><p class="result-note">Selecciona archivos leídos para comprobar sus importaciones localmente. El código no se ejecuta ni se envía a un modelo.</p><button class="connection-action" :disabled="disabled||busy||!canAdd" @click="add">Añadir archivo a revisión DDD</button><ul><li v-for="item in selected" :key="item.path"><code>{{ item.path }}</code><button type="button" :aria-label="`Retirar ${item.path} de revisión DDD`" :disabled="busy" @click="selected=selected.filter(value=>value.path!==item.path);report=undefined">×</button></li></ul><details><summary>Convención de capas y alias</summary><p>Capas: domain/dominio, application/aplicacion, infrastructure/infraestructura/adapters, presentation/ui. El prefijo anterior a la capa identifica el contexto. Los contratos compartidos se señalan para revisión.</p><label>Prefijo de alias<input v-model="prefix" placeholder="@/" :disabled="busy"/></label><label>Directorio relativo del alias<input v-model="directory" placeholder="src" :disabled="busy"/></label><p>Vacía el prefijo si no usas alias. Las rutas relativas siempre se analizan.</p></details><button type="button" class="connection-action" :disabled="disabled||busy||!selected.length" @click="check">{{ busy?'Comprobando dependencias…':'Comprobar reglas DDD' }}</button><p v-if="error" role="alert" class="result-note">{{ error }}</p><div v-if="report" class="architecture-report" role="status"><strong>{{ report.findings.length?`${report.findings.length} dependencias para corregir`:report.status==='partial'?'Comprobación parcial, revisa los límites':'Sin infracciones en el alcance analizado' }}</strong><p>{{ report.analyzed }}/{{ report.selected }} archivos analizados · {{ report.imports }} importaciones · {{ new Date(report.checkedAt).toLocaleString('es-PE') }}</p><article v-for="(finding,index) in report.findings" :key="index"><code>{{ finding.path }}:{{ finding.line }}</code><p>{{ finding.dependency }} · {{ finding.rule }}</p><p>{{ finding.message }}</p></article><p v-for="(item,index) in report.uncertainties" :key="index"><code>{{ item.path }}:{{ item.line }}</code> — {{ item.reason }}</p><p class="result-note">{{ report.scope }}</p><p class="result-note">Informe de las versiones seleccionadas, no una certificación de la arquitectura. Vuelve a leer los archivos después de editarlos.</p><button class="connection-action" @click="download">Descargar informe DDD</button></div></section></template>
<style scoped>.architecture-check{border-top:1px solid #294248;padding:20px 0;margin-top:20px}.architecture-check p,.architecture-check label,.architecture-check summary{font-size:12px;line-height:1.6}.architecture-check ul{list-style:none;padding:0}.architecture-check li{display:flex;justify-content:space-between;gap:12px;padding:6px}.architecture-check code{overflow-wrap:anywhere;font-size:11px}.architecture-check li button{background:transparent;color:#e4b8b8;border:0;cursor:pointer}.architecture-check label{display:block;margin:8px 0}.architecture-check input{display:block;width:100%;max-width:320px;padding:8px;background:#08151a;border:1px solid #294248;color:#d9f1eb;border-radius:4px}.architecture-check details{margin:12px 0;color:#94b1bd}.architecture-report{padding:14px;background:#091c21;border:1px solid #294248;border-radius:6px;margin-top:12px}.architecture-report article{border-left:2px solid #eeaa77;padding:8px 12px;margin-top:12px}</style>
